'use strict';
const $=id=>document.getElementById(id);
const {SurvivalEngine,SPEEDS,paceFor,norm,speechMatches,SpeechLedger,typingPlan}=InkEngine;
const gameAudio=new InkAudio.GameAudio();
function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function saveLocal(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}
const validCustom=q=>q&&typeof q.prompt==='string'&&q.prompt.trim().length>0&&q.prompt.length<=120&&typeof q.answer==='string'&&/^[A-Z]{1,12}$/i.test(q.answer)&&['vocabulary','spelling'].includes(q.mode)&&[1,2,3].includes(Number(q.level));
let custom=readLocal('ra-custom',[]);custom=Array.isArray(custom)?custom.filter(validCustom).map(q=>({...q,level:Number(q.level),answer:q.answer.toUpperCase()})):[];
let config=null,engine=null,status='setup',sound=false,typeTimer=null,lastFrame=0,frameId=0,runToken=0,persistentError='',lastReadingAt=0;
let micTesting=false,micCheckToken=0;
const micLedgers=new Map();
const voiceLedgers=new Map();
const elements=new Map(),skillNames={numbers:'Numbers',letters:'Letters',words:'Vocabulary',spelling:'Names & places',mixed:'Mixed swarm',ipa:'IPA words'};
const voice=new InkVoice.VoiceController({onText:(alternatives,meta)=>micTesting?checkMicAnswers(alternatives,meta):handleSpeech(alternatives,meta),onTranscript:({text,final,alternatives})=>{const el=$(micTesting?'micCheckHeard':'voiceTranscript');el.textContent=`${final?'Browser heard':'Browser hearing'}: “${text}”`;el.title=alternatives.join(' / ');},onReady:()=>{if(engine&&config?.control==='voice'){engine.voiceReady=true;if(status==='playing')gameAudio.resume()}},onWaiting:()=>{if(engine&&config?.control==='voice'){engine.voiceReady=false;if(status==='playing')gameAudio.pause()}},onStatus:text=>{if(micTesting)$('micCheckStatus').textContent=text;else if(config?.control==='voice')setReading(text)},onFatal:message=>{if(micTesting){stopMicCheck();$('micCheckStatus').textContent=message;return}persistentError=message;if(status==='playing')pauseGame(message);else $('setupStatus').textContent=message;}});
function stopMicCheck(){if(!micTesting)return;micCheckToken++;micTesting=false;voice.stop();$('micCheckBtn').textContent='Check microphone ◉';$('micCheckBtn').setAttribute('aria-pressed','false');$('micCheckStatus').textContent='Microphone check stopped.';}
async function toggleMicCheck(){if(micTesting){stopMicCheck();return}if(status!=='setup')return;const token=++micCheckToken;micTesting=true;micLedgers.clear();gameAudio.stop();$('micCheckBtn').textContent='Stop microphone check ■';$('micCheckBtn').setAttribute('aria-pressed','true');$('micCheckResult').textContent='';$('micCheckHeard').textContent='Browser heard: —';try{await voice.start(currentSetup().accent);if(token!==micCheckToken)return;$('micCheckStatus').textContent='Listening. Say “four”, “letter B”, or “ninety-eight”.';}catch(err){if(token!==micCheckToken)return;stopMicCheck();$('micCheckStatus').textContent=err.message;}}
function checkMicAnswers(alternatives,meta){let ledger=micLedgers.get(meta.utterance);if(!ledger){ledger=new SpeechLedger();micLedgers.set(meta.utterance,ledger);if(micLedgers.size>40)micLedgers.delete(micLedgers.keys().next().value)}const active=[{id:1,q:{kind:'numbers',answer:'4'}},{id:2,q:{kind:'letters',answer:'B'}},{id:3,q:{kind:'numbers',answer:'98'}}];let best=[];for(const text of alternatives){const matches=ledger.peek(text,active,numberToWords,meta);if(matches.length>best.length)best=matches}if(best.length){ledger.commit(best);$('micCheckResult').textContent=`✓ Matched: ${best.map(m=>m.answer).join(' · ')}. Ready for the swarm!`;}else if(meta.final&&!ledger.consumed.size)$('micCheckResult').textContent='No match yet. Try one target at a time, or change the speech language above.';}
$('micCheckBtn').onclick=toggleMicCheck;
function setReading(text,type=''){$('liveReading').textContent=text;$('liveReading').parentElement.className='live-reading '+type;lastReadingAt=performance.now()}
function currentSetup(){const f=new FormData($('setupForm'));return{skill:f.get('skill'),control:f.get('control'),range:Number(f.get('range')),level:Number(f.get('level')),speed:f.get('speed'),duration:Number(f.get('duration')),accent:f.get('accent'),sound:f.get('sound')==='on',music:f.get('music')==='on'};}
function setupChanges(){stopMicCheck();const supported=InkVoice.VoiceController.supported();document.querySelector('[name=control][value=voice]').disabled=!supported;let c=currentSetup();if((c.control!=='voice'||!supported)&&['letters','ipa'].includes(c.skill)){document.querySelector('[name=skill][value=numbers]').checked=true;c=currentSetup();}document.querySelectorAll('[name=skill]').forEach(r=>{r.disabled=['letters','ipa'].includes(r.value)&&(c.control!=='voice'||!supported)});$('rangeLabel').hidden=!['numbers','mixed'].includes(c.skill);$('wordLevelLabel').hidden=!['words','spelling','mixed'].includes(c.skill);$('voiceOptions').hidden=c.control!=='voice';const notes={numbers:'Read number words. Answer with digits only: ninety-eight → 98. Written number words do not count.',letters:'Say each letter’s name. Single letters are reserved for microphone speaking practice.',words:'Read a clue and answer with the word. Speak mode shows the word for you to say aloud.',spelling:'Spell a name or place with CAPITAL letters. In Speak mode, say it aloud.',mixed:c.control==='voice'?'Numbers, letter names and words arrive together. Say each target clearly.':'Numbers and vocabulary arrive together. Single-letter targets are reserved for Speak mode.',ipa:'Say the whole word represented by its British English IPA transcription.'};$('skillNote').textContent=notes[c.skill];$('controlNote').textContent=c.control==='type'?'Before playing, switch to an English keyboard and turn off UniKey / Vietnamese input. Complete answers fire immediately; numbers need digits only.':'Say one or several visible targets. Stable speech updates fire before the sentence finishes. Voice mode uses a smaller, slower swarm.';if(!supported){$('voiceOption').title='Speech recognition is unavailable in this browser.';$('setupStatus').textContent='Speak mode needs a browser with speech recognition. Typing is ready.';}}
$('setupForm').addEventListener('change',setupChanges);
function showPage(page){if(page!=='setup')stopMicCheck();$('setupView').hidden=page!=='setup';$('bankView').hidden=page!=='bank';$('gameView').hidden=page!=='game';$('siteHeader').hidden=page==='game';$('siteFooter').hidden=page==='game';document.body.style.overflow=page==='game'?'hidden':'';$('homeNav').classList.toggle('active',page==='setup');$('bankNav').classList.toggle('active',page==='bank');if(page!=='game')window.scrollTo({top:0,behavior:'instant'});if(page==='bank')renderBank();}
function stopInputs(){stopMicCheck();clearTimeout(typeTimer);voice.stop();window.speechSynthesis?.cancel();}
async function startRun(){if(status==='starting'||status==='countdown')return;config=currentSetup();if(!['type','voice'].includes(config.control)){setupError('Choose Type or Speak.');return}if(['ipa','letters'].includes(config.skill)&&config.control!=='voice'){setupError('Letters and IPA cards use Speak mode.');return}if(config.control==='voice'&&!InkVoice.VoiceController.supported()){setupError('This browser does not support Speak mode. Choose Type.');return}const token=++runToken;status='starting';$('startBtn').disabled=true;gameAudio.stop();gameAudio.prepare();gameAudio.configure({...config,voice:config.control==='voice'});$('pauseMusic').checked=config.music;$('pauseEffects').checked=config.sound;$('setupStatus').className='setup-status';$('setupStatus').textContent=config.control==='voice'?'Allow the microphone request to start speaking.':'Opening the gates…';persistentError='';stopInputs();try{if(config.control==='voice')await voice.start(config.accent);if(token!==runToken)return;voiceLedgers.clear();elements.clear();$('enemyLayer').replaceChildren();$('spellLayer').replaceChildren();$('liveAnswer').value='';$('pauseOverlay').hidden=true;$('comboBadge').hidden=true;$('countdownOverlay').hidden=false;$('arenaHint').classList.remove('faded');$('arenaHint').innerHTML=config.control==='type'?'TYPE TO STRIKE.<small>Complete answers fire immediately.</small>':'SAY IT. SLAY IT.<small>Say one or several visible targets.</small>';$('typingBar').hidden=config.control!=='type';$('voiceTranscript').hidden=config.control!=='voice';$('voiceTranscript').textContent='Browser heard: —';$('inputIcon').textContent=config.control==='type'?'⌨':'◉';$('inputHelp').textContent=config.control==='type'?'COMPLETE ANSWERS FIRE FAST · ENTER ALSO WORKS':'STABLE SPEECH FIRES EARLY · MULTIPLE ANSWERS WELCOME';$('runTag').textContent=`${skillNames[config.skill].toUpperCase()} / ${config.control.toUpperCase()}`;$('paceTag').textContent=SPEEDS[config.speed].name.toUpperCase();$('liveAnswer').inputMode=config.skill==='numbers'?'numeric':'text';$('liveAnswer').placeholder=config.skill==='numbers'?'Digits only, e.g. 98…':'Type the answer…';sound=config.sound;showPage('game');status='countdown';$('pauseBtn').disabled=true;$('gameScore').textContent='0000';$('gameHearts').textContent='♥♥♥♥♥';$('gameHearts').setAttribute('aria-label','5 hearts');$('waveLabel').textContent='WAVE 01';$('gameTime').textContent=config.duration?formatTime(config.duration):'∞';setReading(config.control==='voice'?'Mic ready. Say a target when it appears.':'Your answer finds its target.');for(const step of ['3','2','1','GO']){if(token!==runToken)return;$('countdownText').textContent=step;$('countdownNote').textContent=step==='GO'?'HOLD THE LINE.':'READY TO HOLD THE LINE?';await new Promise(resolve=>setTimeout(resolve,step==='GO'?350:650));}if(token!==runToken)return;engine=new SurvivalEngine({pool:InkContent.poolFor(config,custom),speed:config.speed,control:config.control,duration:config.duration,onEvent:handleEvent});engine.voiceReady=config.control!=='voice'||voice.ready;status='playing';gameAudio.start({...config,travel:engine.speed.travel,voice:config.control==='voice'});updateSpacing();$('countdownOverlay').hidden=true;$('pauseBtn').disabled=false;if(config.control==='type')$('liveAnswer').focus({preventScroll:true});updateHUD();lastFrame=performance.now();cancelAnimationFrame(frameId);frameId=requestAnimationFrame(frame);saveLocal('inkfang-last-setup',config);if(document.hidden)pauseGame('The tab was hidden. Your run is safe.');}catch(err){if(token!==runToken)return;stopInputs();status='setup';showPage('setup');setupError(err.message);}finally{$('startBtn').disabled=false;}}
function setupError(message){$('setupStatus').textContent=message;$('setupStatus').className='setup-status error';status='setup';}
function frame(now){if(status==='playing'&&engine){const dt=Math.min((now-lastFrame)/1000,.1);engine.update(dt);renderPositions();updateHUD();if(engine.elapsed>2)$('arenaHint').classList.add('faded');}lastFrame=now;if(['playing','paused'].includes(status))frameId=requestAnimationFrame(frame);}
function updateSpacing(){if(!engine)return;const heights=[...elements.values()].map(el=>el.offsetHeight);const needed=(Math.max(110,...heights)+18)/Math.max(110,$('arena').clientHeight-170);engine.spacing=Math.max(engine.baseSpacing,Math.min(1.25,needed));}
function renderPositions(){const h=$('arena').clientHeight;for(const e of engine.enemies){const el=elements.get(e.id);if(el)el.style.top=(80+e.y*Math.max(110,h-170))+'px';}}
function addEnemy(e){const el=document.createElement('div');el.className='enemy'+(e.lane?' lane-one':'');el.dataset.kind=e.q.kind;const target=document.createElement('span');target.className='target-label';target.textContent=e.q.display;target.setAttribute('aria-label',`Target: ${e.q.display}`);if(e.q.display.length>70)target.classList.add('long-target');const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 150 110');svg.setAttribute('aria-hidden','true');const use=document.createElementNS('http://www.w3.org/2000/svg','use');use.setAttribute('href','#ink-beast');svg.append(use);const palette=['#ff9678','#c4b6e9','#a2d6cc','#e8c47a','#bfdb86'];svg.style.color=palette[e.id%palette.length];const hp=document.createElement('div');hp.className='enemy-hp';hp.append(document.createElement('i'));const hint=document.createElement('span');hint.className='damage-hint';el.append(target,svg,hp,hint);elements.set(e.id,el);$('enemyLayer').append(el);queueMicrotask(updateSpacing);}
function handleEvent(event){if(event.type==='spawn'){addEnemy(event.enemy);if(status==='playing')gameAudio.effect('spawn');return}if(event.type==='kill'){const el=elements.get(event.enemy.id);if(el){el.classList.add('dying');setTimeout(()=>el.remove(),300);elements.delete(event.enemy.id)}spellAt(event.enemy,`+${event.points}`);gameAudio.effect(engine.combo>=3?'combo':'hit',engine.combo);return}if(event.type==='partial'){const el=elements.get(event.enemy.id);if(el){el.querySelector('.enemy-hp i').style.width=(100-event.enemy.damage*100)+'%';el.querySelector('.damage-hint').textContent=[...norm(event.enemy.q.answer)].map((c,i)=>event.enemy.locked.has(i)?c:'_').join(' ');el.classList.remove('damaged');void el.offsetWidth;el.classList.add('damaged')}spellAt(event.enemy,'HIT');gameAudio.effect('chip');return}if(event.type==='escape'){const el=elements.get(event.enemy.id);el?.remove();elements.delete(event.enemy.id);$('arena').classList.remove('hurt');void $('arena').offsetWidth;$('arena').classList.add('hurt');setReading(`Escaped: ${event.enemy.q.display} → ${event.enemy.q.answer}`,'warning');gameAudio.effect('escape');return}if(event.type==='end')finishRun(event.reason);}
function spellAt(e,label){const layer=$('spellLayer'),w=$('arena').clientWidth,h=$('arena').clientHeight,x=w*(e.lane?.75:.25),y=80+e.y*Math.max(110,h-170)-40,sx=w/2,sy=h-46,dx=x-sx,dy=y-sy;const beam=document.createElement('div');beam.className='hit-beam';beam.style.left=sx+'px';beam.style.top=sy+'px';beam.style.width=Math.hypot(dx,dy)+'px';beam.style.transform=`rotate(${Math.atan2(dy,dx)}rad)`;const pop=document.createElement('div');pop.className='hit-pop';pop.textContent=label;pop.style.left=x-15+'px';pop.style.top=y+'px';layer.append(beam,pop);setTimeout(()=>{beam.remove();pop.remove()},800);}
function handleAnswer(value,source){if(status!=='playing'||!engine)return;const result=engine.submit(value,{partial:source!=='voice'});if(result.type==='kill'){setReading(`${value} → ${result.enemy.q.answer} · Target down!`,'success');if(source==='type')$('liveAnswer').value='';}else if(result.type==='partial'){setReading(`${value} · Partial hit. Finish ${result.enemy.q.answer.length} characters to defeat it.`,'success');}else setReading(`Read: ${value} · No match yet. Try again.`,'warning');$('arenaHint').classList.add('faded');updateHUD();}
function handleSpeech(alternatives,meta={utterance:'legacy',final:true,stable:true}){if(status!=='playing'||!engine)return;let ledger=voiceLedgers.get(meta.utterance);if(!ledger){ledger=new SpeechLedger();voiceLedgers.set(meta.utterance,ledger);if(voiceLedgers.size>40)voiceLedgers.delete(voiceLedgers.keys().next().value)}let best=[];for(const transcript of alternatives){const matches=ledger.peek(transcript,engine.enemies,numberToWords,{...meta,lettersOnly:config.skill==='letters'});if(matches.length>best.length)best=matches;}if(best.length){ledger.commit(best);let hits=0;for(const match of best){if(!engine.enemies.some(e=>e.id===match.id))continue;const result=engine.submit(match.answer,{partial:false,targetId:match.id});if(result.type==='kill')hits++;}if(hits)setReading(`${best.map(m=>m.answer).join(' · ')} → ${hits} target${hits===1?'':'s'} down!`,'success');updateHUD();return}if(meta.final&&!ledger.consumed.size)setReading(`Heard “${alternatives[0]||''}” · No target matched. Try again.`,'warning');}
function formatTime(seconds){seconds=Math.max(0,Math.ceil(seconds));return`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}
function updateHUD(){if(!engine)return;gameAudio.setWave(engine.wave);gameAudio.setPace(engine.speed.travel/engine.multiplier);$('gameScore').textContent=String(engine.score).padStart(4,'0');$('waveLabel').textContent=`WAVE ${String(engine.wave).padStart(2,'0')}`;$('gameTime').textContent=config.duration?formatTime(config.duration-engine.elapsed):formatTime(engine.elapsed);$('gameHearts').textContent='♥'.repeat(Math.max(0,engine.lives))+'♡'.repeat(5-Math.max(0,engine.lives));$('gameHearts').setAttribute('aria-label',`${engine.lives} hearts`);$('comboBadge').hidden=engine.combo<2;$('comboBadge').textContent=`${engine.combo}× COMBO`;}
function pauseGame(message='Your run is paused. Monsters wait here.'){if(status!=='playing')return;status='paused';stopInputs();gameAudio.pause();$('pauseTitle').innerHTML=persistentError?'MIC NEEDS<br>A MOMENT.':'SWARM<br>ON HOLD.';$('pauseNote').textContent=message;$('pauseOverlay').hidden=false;$('resumeBtn').disabled=false;}
async function resumeGame(){if(status!=='paused')return;$('resumeBtn').disabled=true;try{if(config.control==='voice')await voice.start(config.accent);persistentError='';$('pauseOverlay').hidden=true;status='playing';gameAudio.resume();lastFrame=performance.now();if(config.control==='type')$('liveAnswer').focus({preventScroll:true});setReading(config.control==='voice'?'Mic on · Say a target.':'Back in the fight.');}catch(err){$('pauseNote').textContent=err.message}finally{$('resumeBtn').disabled=false;}}
function returnSetup(){runToken++;stopInputs();gameAudio.stop();cancelAnimationFrame(frameId);status='setup';engine=null;voiceLedgers.clear();elements.clear();$('enemyLayer').replaceChildren();$('countdownOverlay').hidden=true;$('pauseOverlay').hidden=true;if($('summaryDialog').open)$('summaryDialog').close();showPage('setup');setupChanges();$('setupStatus').className='setup-status';$('setupStatus').textContent='Change your setup. Then take another shot.';window.InkGuide?.setStep(0);}
function finishRun(reason){if(status==='ended')return;status='ended';stopInputs();gameAudio.stop();gameAudio.effect(reason==='time'?'win':'end');cancelAnimationFrame(frameId);$('resultEyebrow').textContent=reason==='time'?'LINE HELD. WELL PLAYED.':'THE SWARM GOT THROUGH. YOUR MAGIC GOT STRONGER.';$('resultTitle').innerHTML=reason==='time'?'YOU HELD<br>THE LINE.':'YOU MADE<br>YOUR MARK.';const badge=InkOnboarding.badgeFor(engine);$('resultBadge').textContent=badge.name;$('resultRank').textContent=badge.glyph;$('summaryDialog').dataset.badge=badge.glyph;$('resultScore').textContent=engine.score;$('resultKills').textContent=engine.kills;$('resultCombo').textContent=engine.bestCombo;$('resultTime').textContent=formatTime(engine.elapsed);const bestKey=`inkfang-v4-best-${config.skill}-${config.control}-${config.speed}-${config.range}-${config.duration}`;const previous=readLocal(bestKey,0);const isBest=engine.score>previous;if(isBest)saveLocal(bestKey,engine.score);$('newBest').hidden=!isBest;$('resultBest').textContent=`Your best: ${Math.max(previous,engine.score)}`;$('resultDetails').textContent=`${skillNames[config.skill]} · ${config.control==='voice'?'Speak':'Type'} · ${SPEEDS[config.speed].name} · Reached wave ${engine.wave}`;$('milestoneLabel').textContent=engine.kills>=50?'Legendary run. Keep going.':'Your next badge';$('milestoneCount').textContent=`${engine.kills} / ${badge.goal} monsters`;$('milestoneFill').style.width=Math.min(100,engine.kills/badge.goal*100)+'%';const review=$('reviewList');review.replaceChildren();const unique=[...new Map(engine.review.map(q=>[q.id,q])).values()];$('reviewTitle').textContent=unique.length?`Revisit ${unique.length} target${unique.length===1?'':'s'} →`:'A clean run. Every target handled. ✓';document.querySelector('.results-review').open=false;if(unique.length){for(const q of unique.slice(0,16)){const row=document.createElement('div');row.className='review-target';const clue=document.createElement('span'),answer=document.createElement('strong'),outcome=document.createElement('small');clue.textContent=q.prompt;answer.textContent=q.answer;outcome.textContent=q.outcome==='escaped'?'Escaped · Try it again':'Recovered after a partial hit';row.append(clue,answer,outcome);review.append(row)}}else review.textContent='Try a faster pace or a bigger number range.';$('summaryDialog').showModal();}
$('setupForm').onsubmit=e=>{e.preventDefault();startRun()};$('pauseBtn').onclick=()=>pauseGame();$('resumeBtn').onclick=resumeGame;$('exitBtn').onclick=returnSetup;$('retryBtn').onclick=()=>{$('summaryDialog').close();status='setup';startRun()};$('setupBtn').onclick=returnSetup;$('summaryDialog').oncancel=e=>{e.preventDefault();returnSetup()};function processTyping(e){clearTimeout(typeTimer);if(status!=='playing'||config?.control!=='type')return;if(e?.isComposing){setReading('Switch to an English keyboard and turn off UniKey / Vietnamese input for instant typing.','warning');return;}const input=$('liveAnswer');input.value=input.value.toUpperCase().slice(0,24);const value=input.value,plan=typingPlan(value,engine.enemies);if(plan.delay===0){handleAnswer(value,'type');return}if(plan.delay===null)return;const activeRun=runToken;typeTimer=setTimeout(()=>{if(activeRun===runToken&&status==='playing'&&input.value===value)handleAnswer(value,'type')},plan.delay);}$('liveAnswer').oncompositionstart=()=>{clearTimeout(typeTimer);if(status==='playing')setReading('Switch to an English keyboard and turn off UniKey / Vietnamese input for instant typing.','warning')};$('liveAnswer').oninput=processTyping;$('liveAnswer').oncompositionend=processTyping;$('liveAnswer').onkeydown=e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();clearTimeout(typeTimer);handleAnswer(e.target.value,'type')}};
$('gameSound').onclick=()=>{if(status==='playing')pauseGame('Adjust your soundtrack and effects. Resume when you’re ready.');$('pauseMusic').focus()};$('pauseMusic').onchange=e=>{config.music=e.target.checked;document.querySelector('[name=music]').checked=config.music;gameAudio.setMusic(config.music)};$('pauseEffects').onchange=e=>{config.sound=e.target.checked;document.querySelector('[name=sound]').checked=config.sound;gameAudio.setEffects(config.sound)};$('musicVolume').oninput=e=>gameAudio.setVolume(Number(e.target.value)/100);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]')){if(status==='playing')pauseGame();else if(status==='paused')resumeGame()}});document.addEventListener('visibilitychange',()=>{if(document.hidden){if(status==='playing')pauseGame('The tab was hidden. Your run is paused.');else gameAudio.stop();}});window.addEventListener('pagehide',()=>{voice.stop();gameAudio.stop()});window.addEventListener('blur',()=>{if(status==='playing')pauseGame('The game lost focus. Your run is paused.');});
function viewport(){const vv=window.visualViewport;document.documentElement.style.setProperty('--play-height',(vv?.height||window.innerHeight)+'px');document.documentElement.style.setProperty('--play-top',(vv?.offsetTop||0)+'px');if(engine&&status==='playing'){updateSpacing();renderPositions();}}window.visualViewport?.addEventListener('resize',viewport);window.visualViewport?.addEventListener('scroll',viewport);window.addEventListener('resize',viewport);viewport();
$('homeNav').onclick=()=>{if(status==='playing')pauseGame();showPage('setup')};$('bankNav').onclick=()=>{gameAudio.stop();showPage('bank')};$('helpBtn').onclick=()=>{stopMicCheck();gameAudio.stop();$('helpDialog').showModal()};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
function teacherBank(){const base={control:'voice',range:1000,level:3};return[...InkContent.poolFor({...base,skill:'mixed'},custom),...InkContent.poolFor({...base,skill:'spelling'},custom),...InkContent.IPA];}
let bankPage=0;const PAGE_SIZE=16;
function filteredBank(){const search=$('bankSearch').value.toLowerCase(),kind=$('bankSkill').value;return teacherBank().filter(q=>(kind==='all'||q.kind===kind)&&[q.prompt,q.answer,q.topic].join(' ').toLowerCase().includes(search));}
function renderBank(){const rows=filteredBank();bankPage=Math.max(0,Math.min(bankPage,Math.ceil(rows.length/PAGE_SIZE)-1));$('bankBody').replaceChildren(...rows.slice(bankPage*PAGE_SIZE,(bankPage+1)*PAGE_SIZE).map(q=>{const tr=document.createElement('tr');for(const text of [q.prompt,q.answer,skillNames[q.kind]||skillNames[q.mode]||q.kind]){const td=document.createElement('td');td.textContent=text;tr.append(td)}return tr}));$('bankResults').textContent=rows.length?`${bankPage*PAGE_SIZE+1}–${Math.min((bankPage+1)*PAGE_SIZE,rows.length)} of ${rows.length} targets`:'No matching targets.';$('prevPage').disabled=bankPage===0;$('nextPage').disabled=(bankPage+1)*PAGE_SIZE>=rows.length;}
$('bankSearch').oninput=()=>{bankPage=0;renderBank()};$('bankSkill').onchange=()=>{bankPage=0;renderBank()};$('prevPage').onclick=()=>{bankPage--;renderBank()};$('nextPage').onclick=()=>{bankPage++;renderBank()};
function download(content,name,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}$('exportBank').onclick=()=>download(JSON.stringify(teacherBank(),null,2),'inkfang-question-bank.json','application/json');$('exportCsv').onclick=()=>{const columns=['id','kind','mode','level','prompt','answer','spoken','topic'];const rows=[columns.join(','),...teacherBank().map(q=>columns.map(k=>'"'+String(q[k]??'').replaceAll('"','""')+'"').join(','))];download('\uFEFF'+rows.join('\r\n'),'inkfang-question-bank.csv','text/csv;charset=utf-8')};$('customForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),q={id:`custom-${Date.now()}`,prompt:f.get('prompt').trim(),answer:f.get('answer').toUpperCase(),mode:f.get('mode'),level:Number(f.get('level')),topic:'Teacher-created'};if(!validCustom(q)){$('bankNotice').textContent='Use 1–12 letters and a non-empty clue.';return}custom.push(q);const saved=saveLocal('ra-custom',custom);renderBank();e.target.reset();$('bankNotice').textContent=saved?'Added. The next run will include it.':'Added for this session. Browser storage is unavailable.'};$('removeCustom').onclick=()=>{if(!custom.length){$('bankNotice').textContent='No custom questions to remove.';return}if(!confirm(`Remove ${custom.length} custom questions from this browser? Export them first if you want a copy.`))return;custom=[];saveLocal('ra-custom',custom);renderBank();$('bankNotice').textContent='Custom questions removed.'};$('importBank').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error('Please use a JSON file smaller than 2 MB.');const rows=JSON.parse(await file.text());if(!Array.isArray(rows)||rows.length>3000)throw Error('Use a JSON array of up to 3,000 questions.');let added=0,skipped=0;const known=new Set(teacherBank().map(q=>[q.prompt,q.answer].join('|')));for(const row of rows){const q={...row,mode:row.mode==='words'?'vocabulary':row.mode,answer:String(row.answer||'').toUpperCase(),level:Number(row.level||1)};if(!validCustom(q)){skipped++;continue}const key=[q.prompt,q.answer].join('|');if(known.has(key))continue;custom.push({id:`import-${Date.now()}-${added}`,mode:q.mode,level:q.level,prompt:q.prompt.trim(),answer:q.answer,topic:'Imported'});known.add(key);added++;}const saved=saveLocal('ra-custom',custom);renderBank();$('bankNotice').textContent=`${added} added; ${skipped} unsupported rows skipped.${saved?'':' Browser storage unavailable.'}`;}catch(err){$('bankNotice').textContent=err.message}e.target.value='';};
setupChanges();

document.addEventListener('visibilitychange',()=>{if(document.hidden)stopMicCheck()});
